Consider the SQL query:
SELECT COUNT(*) FROM Employees WHERE DeptID NOT IN (SELECT DeptID FROM ClosedDepts);
If the subquery returns (10, NULL), how many rows will the outer query return?

What will be the output of the following C program?
#include <stdio.h>
int main() {
 int a[] = {5, 15, 25, 35, 45};
 int *ptr = a + 3;
 printf("%d %d", *(ptr - 2), *ptr);
 return 0;
}

What is the output of the following C code?
#include <stdio.h>
void modify(int *a, int b) {
 *a = *a + b;
 b = b + 10;
}
int main() {
 int x = 10, y = 5;
 modify(&x, y);
 printf("%d %d", x, y);
 return 0;
}

